[tool.uv.workspace]
members = ["livekit-plugins/*", "livekit-agents", "examples/avatar", "examples/drive_thru", "examples/expressive_agent", "examples/frontdesk", "examples/healthcare", "examples/homepage", "examples/hotel_receptionist", "examples/inference", "examples/survey", "examples/voice_agents"]
exclude = [
    "livekit-plugins/community",
    "livekit-plugins/livekit-blockguard",
    "livekit-plugins/livekit-durable",
]

[dependency-groups]
dev = [
    "python-dotenv>=1.0.1",
    "mypy",
    "scikit-learn",
    "pytest>=9.0.3,<9.1",
    "ruff",
    "pytest-asyncio>=0.25.3",
    "pytest-asyncio-concurrent==0.5.2",
    "jiwer>=3.1.0",
    "scipy>=1.13.1",
    "tiktoken>=0.9.0",
    "pytest-xdist>=3.8.0",
    "playwright>=1.58.0",
]
docs = ["pdoc3", "setuptools", "beautifulsoup4", "markdownify"]
typing = [
    # .pyi stubs, never used at runtime
    "pandas-stubs>=3.0.3.260530",
    "scipy-stubs>=1.17.1.5",
    "types-aiofiles>=25.1.0.20260518",
    "types-cffi>=2.0.0.20260518",
    "types-defusedxml>=0.7.0.20260504",
    "types-grpcio>=1.0.0.20260607",
    "types-grpcio-status>=1.0.0.20260408",
    "types-gunicorn>=26.0.0.20260518",
    "types-openpyxl>=3.1.5.20260518",
    "types-pexpect>=4.9.0.20260518",
    "types-psutil>=7.2.2.20260518",
    "types-pyasn1>=0.6.0.20260408",
    "types-pyaudio>=0.2.16.20260508",
    "types-pygments>=2.20.0.20260518",
    "types-pysocks>=1.7.1.20260518",
    "types-python-dateutil>=2.

# SPDX-FileCopyrightText: Copyright (c) 2026 NVIDIA CORPORATION & AFFILIATES. All rights reserved.
# SPDX-License-Identifier: Apache-2.0

[workspace]
resolver = "3"
members = [
    "crates/libsy",
    "crates/libsy-llm-client",
    "crates/switchyard-py",
    "crates/protocol",
    "crates/switchyard-server",
    "crates/switchyard-skill-distillation",
    "crates/switchyard-soak",
    "crates/switchyard-translation",
]

[workspace.package]
version = "0.2.0"
authors = ["NVIDIA Corporation"]
edition = "2024"
license = "Apache-2.0"
repository = "https://github.com/NVIDIA-NeMo/Switchyard"
rust-version = "1.96.1"

[workspace.dependencies]
async-stream = "0.3"
async-trait = "0.1"
futures = "0.3"
futures-util = "0.3"
http = "1"
httpdate = "1"
jsonschema = { version = "0.49.4", default-features = false }
jsonptr = { version = "0.8.1", default-features = false, features = ["std", "json", "resolve"] }
parking_lot = "0.12"
rand = "0.10"
regex = "1"
reqwest = { version = "0.13.4", default-features = false, features = ["json", "rustls", "stream"] }
serde = { version = "1", features = ["derive"] }
serde_json = { version = "1", features = ["preserve_order"] }
switchyard-libsy = { path = "crates/libsy", version = "0.2.0" }
switchyard-llm-client = { path = "crates/libsy-llm-client", version = "0.2.0" }
switchyard-protocol = { path = "crates/protocol", version = "0.2.0" }
switchyard-server = { path = "crates/switchyard-server", version = "0.2.0" }
switchyard-translation = { path = "crates/switchyard-translation", version = "0.2.0" }
thiserror = "2"
tokio = { version = "1", features = ["full"] }
tracing = { version = "0.1", default-features = false, features = ["attributes", "std"] }
tracing-opentelemetry = "0.33"
tracing-subscriber = { version = "0.3", features = ["env-filter"] }

[workspace]
members = [
    "crates/buzz-relay",
    "crates/buzz-core",
    "crates/buzz-conformance",
    "crates/buzz-push-gateway",
    "crates/buzz-db",
    "crates/buzz-pubsub",
    "crates/buzz-auth",
    "crates/buzz-search",
    "crates/buzz-audit",
    "crates/buzz-acp",
    "crates/buzz-agent",
    "crates/sprig",
    "crates/buzz-test-client",
    "crates/buzz-ws-client",
    "crates/buzz-admin",
    "crates/buzz-deletion",
    "crates/buzz-workflow",
    "crates/buzz-media",
    "crates/buzz-cli",
    "crates/buzz-pairing-cli",
    "crates/buzz-sdk",
    "crates/buzz-persona",
    "crates/git-credential-nostr",
    "crates/git-sign-nostr",
    "crates/buzz-pair-relay",
    "crates/buzz-relay-mesh",
    "crates/buzz-dev-mcp",
    "crates/buzz-voice",
    "crates/buzz-backend-kubernetes",
    "crates/buzz-datastore-tracing",
    "examples/countdown-bot",
]
exclude = ["desktop/src-tauri"]
resolver = "2"

[workspace.package]
version = "0.1.0"
edition = "2021"
rust-version = "1.88.0"
license = "Apache-2.0"
repository = "https://github.com/block/sprout"

[workspace.dependencies]
# Runtime
tokio       = { version = "1", features = ["rt-multi-thread", "macros", "net", "time", "sync", "io-util", "signal", "process"] }
tokio-util  = { version = "0.7", features = ["rt", "codec"] }

# HTTP + WebSocket
axum        = { version = "0.8", features = ["ws", "macros"] }
tower       = { version = "0.5", features = ["timeout", "util", "limit"] }
tower-http  = { version = "0.6", features = ["trace", "cors", "compression-gzip", "limit", "timeout", "fs"] }

# Database
sqlx = { version = "0.9", features = [
    "runtime-tokio", "tls-rustls", "postgres", "uuid", "chrono", "json"
] }

# Redis
redis        = { version = "1.0", features = ["tokio-comp", "connection-manager", "tokio-rustls-comp"] }
deadpool-redis = { version = "0.23", features = ["rt_tokio_1"] }

# Kubernetes (buzz-backend-kubernetes provider). No `ring` feature here: the
# process-level CryptoProvider is installed explicitly at startup, matching
# buzz-cli/buzz-acp/buzz-admin/buzz-relay/buzz-dev-mcp — see the comment on the
# crate's own rustls dependency.
kube = { version = "2.0", default-features = false, features = ["client", "rustls-tls"] }
k8s-openapi = { version = "0.26", features = ["v1_31"] }

# Nostr
nostr = { version = "0.44", features = ["nip44", "nip98"] }

# Serialization
serde       = { version = "1", features = ["derive"] }
postcard    = { version = "1", default-features = false, features = ["use-std"] }

# Inter-relay mesh transport (buzz-relay-mesh)
iroh = { version = "1.0.0-rc.0", default-features = false, features = ["tls-ring"] }
serde_json  = "1"
serde_yaml  = "0.9"
evalexpr    = "11"
cron        = "0.16"
# Observability
tracing                     = "0.1"
tracing-subscriber          = { version = "0.3", features = ["env-filter", "json"] }
tracing-opentelemetry       = { version = "0.33" }
opentelemetry               = { version = "0.32", features = ["trace"] }
opentelemetry_sdk           = { version = "0.32", features = ["trace", "rt-tokio"] }
opentelemetry-otlp          = { version = "0.32", default-features = false, features = ["trace", "grpc-tonic", "tls-ring"] }
metrics             = "0.24"
metrics-exporter-prometheus = "0.18"
metrics-util        = "0.20"

# Error handling
thiserror = "2"
anyhow    = "1"

# Utilities
uuid    = { version = "1", features = ["v4", "serde"] }
chrono  = { version = "0.4", features = ["serde"] }

# HTTP client (webhook delivery)
reqwest = { version = "0.13", features = ["json", "rustls"], default-features = false }

# Cryptography
sha2      = "0.11"
hex       = "0.4"
hmac      = "0.13"
base64    = "0.22"

# Randomness
rand = "0.10"
subtle = "2.6"
zeroize = "1.8"

# Concurrent data structures
dashmap = "6"
moka    = { version = "0.12", features = ["sync"] }

# Async stream utilities
futures-util = "0.3"

# WebSocket client (test client)
tokio-tungstenite = { version = "0.29", features = ["rustls-tls-webpki-roots"] }
url = "2"

# Property-based testing (dev-only)
proptest = "1"

# MCP SDK (used by buzz-dev-mcp and buzz-agent)
rmcp = { version = "1.1.0", features = ["server", "transport-io", "macros"] }
schemars = { version = "1", default-features = false }

# Internal crates
buzz-core = { path = "crates/buzz-core" }
buzz-conformance = { path = "crates/buzz-conformance" }
buzz-db = { path = "crates/buzz-db" }
buzz-deletion = { path = "crates/buzz-deletion" }
buzz-auth = { path = "crates/buzz-auth" }
buzz-pubsub = { path = "crates/buzz-pubsub" }
buzz-search = { path = "crates/buzz-search" }
buzz-audit = { path = "crates/buzz-audit" }
buzz-workflow = { path = "crates/buzz-workflow" }
buzz-media = { path = "crates/buzz-media" }
buzz-sdk = { path = "crates/buzz-sdk" }
buzz-ws-client = { path = "crates/buzz-ws-client" }
buzz-relay-mesh = { path = "crates/buzz-relay-mesh" }
buzz-datastore-tracing = { path = "crates/buzz-datastore-tracing" }

# CI profile — builds the relay for desktop e2e. Dependencies keep full
